func (cs *Cursors) cursor(c Cursor) (xproto.Cursor, error) {
	if xc, ok := cs.themeM[c]; ok {
		return xc, nil
	}
	if xc, err := cs.loadThemeCursor(c); err == nil {
		cs.themeM[c] = xc
		return xc, nil
	}

	xc, ok := cs.m[c]
	if !ok {
		xc2, err := cs.loadCursor(c)
		if err != nil {
			return 0, err
		}
		cs.m[c] = xc2
		xc = xc2
	}
	return xc, nil
